export function DrillThrough({
  metric = "{{metric}}",
  navigated = {{navigated}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: 300, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
      <div style={{ height: 90, display: "flex", alignItems: "flex-end", gap: 10 }}>
        <div style={{ flex: 1, height: "30%", background: "#24143018", borderRadius: "4px 4px 0 0" }} />
        <div style={{ flex: 1, height: "52%", background: "#24143018", borderRadius: "4px 4px 0 0" }} />
        <div style={{ flex: 1, height: "88%", background: accent, borderRadius: "4px 4px 0 0", position: "relative", cursor: "pointer" }}>
          <span style={{ position: "absolute", top: -20, left: "50%", transform: "translateX(-50%)", fontSize: 10, whiteSpace: "nowrap", color: accent, fontWeight: 700 }}>{metric}</span>
        </div>
        <div style={{ flex: 1, height: "40%", background: "#24143018", borderRadius: "4px 4px 0 0" }} />
      </div>
      {navigated && <>
        <div style={{ textAlign: "center", color: accent, fontSize: 16, margin: "10px 0" }}>&#8595;</div>
        <div style={{ padding: "12px 14px", borderRadius: 8, background: "#FAF7F2", border: "1.5px solid " + accent }}>
          <p style={{ margin: "0 0 4px", fontWeight: 700 }}>Transaction #48213</p>
          <p style={{ margin: 0, color: "#241430aa" }}>Order &mdash; $412.00 refunded</p>
        </div>
      </>}
    </div>
  );
}
